let M, last;const $=id=>document.getElementById(id),C={A:'#1459b5',B:'#c4530a'};const pct=v=>`${(100*v).toFixed(1)}%`,num=id=>Number($(id).value),eq=(d,n,a)=>d*(d/n+a)/(2+a);const dot=(x,y)=>x.reduce((s,v,i)=>s+v*y[i],0);const quant=(a,p)=>{a.sort((x,y)=>x-y);const i=(a.length-1)*p,l=Math.floor(i);return a[l]+(a[Math.ceil(i)]-a[l])*(i-l)};const vec=(base,d)=>[...base,(d-105)/10,((d-105)/10)**2];
function survival(base,d){const x=vec(base,d),r=Math.exp(dot(x,M.beta));const s=M.H.map(h=>Math.exp(-h*r));const runs=M.bootstrap.map(b=>{const rr=Math.exp(dot(x,b.b));return b.H.map(h=>Math.exp(-h*rr))});const lo=s.map((_,i)=>quant(runs.map(v=>v[i]),.025)),hi=s.map((_,i)=>quant(runs.map(v=>v[i]),.975));return{s,lo,hi}}
