const narrow=()=>typeof matchMedia==='function'&&matchMedia('(max-width:760px)').matches;
function chart(id,W,H,xmin,xmax,ymin,ymax,xticks,yticks,xlabel,ylabel){const el=$(id),pad={l:52,r:20,t:22,b:44};if(el.setAttribute)el.setAttribute('viewBox',`0 0 ${W} ${H}`);const xp=x=>pad.l+(x-xmin)/(xmax-xmin)*(W-pad.l-pad.r),yp=y=>H-pad.b-(y-ymin)/(ymax-ymin)*(H-pad.t-pad.b);let s=`<title>${el.getAttribute('aria-label')}</title><rect width="${W}" height="${H}" fill="white"/>`;yticks.forEach(y=>s+=`<line x1="${pad.l}" x2="${W-pad.r}" y1="${yp(y)}" y2="${yp(y)}" stroke="#e5eceb"/><text x="${pad.l-10}" y="${yp(y)+4}" text-anchor="end" fill="#6b8187" font-size="11">${Math.round(y*100)}%</text>`);xticks.forEach(x=>s+=`<text x="${xp(x)}" y="${H-24}" text-anchor="middle" fill="#6b8187" font-size="11">${x}</text>`);s+=`<text x="${W/2}" y="${H-5}" text-anchor="middle" fill="#6b8187" font-size="11">${xlabel}</text><text x="${pad.l}" y="12" fill="#6b8187" font-size="10">${ylabel}</text>`;return{el,xp,yp,s,finish(){el.innerHTML=this.s}}}
function path(xs,ys,xp,yp){return xs.map((v,i)=>(i?'L':'M')+xp(v).toFixed(2)+','+yp(ys[i]).toFixed(2)).join(' ')}
function band(c,xs,lo,hi,col){c.s+=`<path d="${path(xs,hi,c.xp,c.yp)} ${xs.slice().reverse().map((v,j)=>'L'+c.xp(v)+','+c.yp(lo[lo.length-1-j])).join(' ')} Z" fill="${col}" opacity=".10"/>`}
