const textAt=(p,i)=>p.ok?`${pct(p.pred.s[i])} (${pct(p.pred.lo[i])}–${pct(p.pred.hi[i])})`:'Outside display limits';const median=p=>{if(!p.ok)return'—';const i=p.pred.s.findIndex(s=>s<=.5);return i<0?'>24 months':M.grid[i].toFixed(2)+' months'};const rows=[['Reirradiation regimen',...ps.map(p=>`${p.dose} Gy / ${p.fx} fx`)],['Dose per fraction',...ps.map(p=>(p.dose/p.fx).toFixed(2)+' Gy')],['Reirradiation EQD2₁₀',...ps.map(p=>p.r10.toFixed(2)+' Gy')],['Cumulative EQD2₁₀',...ps.map(p=>p.d10.toFixed(2)+' Gy')],['Cumulative EQD2₃',...ps.map(p=>p.d3.toFixed(2)+' Gy')],['6-month OS',...ps.map(p=>textAt(p,24))],['12-month OS',...ps.map(p=>textAt(p,48))],['18-month OS',...ps.map(p=>textAt(p,72))],['Model-estimated median OS',...ps.map(median)],['Documented RN in dose group',...ps.map(p=>`${pct(p.rn.p)} (${p.rn.events}/${p.rn.n}); ${p.rn.label}`)]];$('comparison').innerHTML=rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('');last.rows=rows;
$('validation').textContent=`Primary model N=${M.modelN}, events=${M.events} · Reproduced hazard nadir ${M.nadir.toFixed(1)} Gy · Bootstrap ${M.bootstrap.length}/200 fits · Cumulative EQD2₁₀ observed range ${M.doseRange.map(x=>x.toFixed(1)).join('–')} Gy · Reirradiation EQD2₁₀ ${M.reDoseRange.map(x=>x.toFixed(1)).join('–')} Gy.`;
