const T0=Date.now(),hideSplash=()=>{const s=$('splash');if(!s||!s.classList)return;setTimeout(()=>{s.classList.add('hide');setTimeout(()=>{if(s.remove)s.remove()},400)},Math.max(0,1600-(Date.now()-T0)))};
